public final class ConnectionId {                 // final: no subclass copying
    private final String value;
    private ConnectionId(String value) { this.value = value; }

    public static ConnectionId parse(String s) { return new ConnectionId(s); }

    @Override protected Object clone() throws CloneNotSupportedException {
        throw new CloneNotSupportedException("identity object: copies are not supported");
    }
    // no copy constructor, no Cloneable, no Serializable
}
